param([switch]$NegativeControls)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
# Actual file transitions use generated bytes in an ordinary temporary folder.
# No private installation/runtime path, ACL, SCM, real token or service is used.
$files=@('WindowsSigninVault.cs','WindowsSigninAdminJournal.cs','WindowsSigninAdminJournalChecks.cs')
$root=Join-Path ([IO.Path]::GetTempPath()) ('soda-admin-journal-checks-'+[guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($root)|Out-Null
$bytes=@{};$original=@{}
foreach($file in $files){$bytes[$file]=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot $file));$original[$file]=[Text.Encoding]::UTF8.GetString($bytes[$file]);[IO.File]::WriteAllBytes((Join-Path $root $file),$bytes[$file])}
$shell=Join-Path ([Environment]::GetFolderPath('System')) 'WindowsPowerShell\v1.0\powershell.exe'
$paths=($files|ForEach-Object {"'"+(Join-Path $root $_).Replace("'","''")+"'"}) -join ','
$program="`$ErrorActionPreference='Stop';try{Add-Type -Path @($paths) -ReferencedAssemblies System.dll,System.Core.dll,System.Security.dll;[SodaDesktopSigninAdminJournalChecks]::Run()}catch{[Console]::Out.WriteLine(`$_.Exception.ToString());exit 1};exit 0"
$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($program))
try{
 $output=& $shell -NoProfile -NonInteractive -EncodedCommand $encoded 2>&1;$code=$LASTEXITCODE;$output|ForEach-Object{[string]$_};if($code -ne 0){throw 'Generated journal checks failed'}
 if($NegativeControls){
  $variants=@(
   @('claim-identity','if(!before.Same(SodaDesktopSigninVault.Facts(claimed.SafeFileHandle)))throw Failure();','if(before==null)throw Failure();','Replaced pending identity was dispatched'),
   @('residue','if(State()!="claim")throw Failure();','if(false)throw Failure();','Claim accepted journal residue'),
   @('claim-digest','if(Digest(bytes)!=expected)throw Failure();','if(false)throw Failure();','Result accepted changed claim digest'),
   @('ack-before-cleanup','try{Atomic("admin.ack.pending","admin.ack",ack);}','try{}','Ack was not published before original removal'),
   @('partial-stage','if(files.Length==0)return "normal";','if(files.Length==0||files.Length==1&&System.IO.Path.GetFileName(files[0])=="admin.result.pending")return "normal";','Partial stage entered normal sharing')
  )
  foreach($variant in $variants){
   $name='WindowsSigninAdminJournal.cs';$before=$original[$name];if(([regex]::Matches($before,[regex]::Escape($variant[1]))).Count -ne 1){throw ('Negative guard changed: '+$variant[0])}
   try{
    [IO.File]::WriteAllText((Join-Path $root $name),$before.Replace($variant[1],$variant[2]));$output=& $shell -NoProfile -NonInteractive -EncodedCommand $encoded 2>&1;$code=$LASTEXITCODE
    'negative '+$variant[0];$output|ForEach-Object{[string]$_};if($code -ne 1 -or -not (($output|Out-String).Contains('System.InvalidOperationException: '+$variant[3]))){throw ('Negative did not fail intended assertion: '+$variant[0])}
   }finally{[IO.File]::WriteAllBytes((Join-Path $root $name),$bytes[$name]);if([Convert]::ToBase64String([IO.File]::ReadAllBytes((Join-Path $root $name))) -cne [Convert]::ToBase64String($bytes[$name])){throw 'Source bytes not restored'}}
  }
  $output=& $shell -NoProfile -NonInteractive -EncodedCommand $encoded 2>&1;$code=$LASTEXITCODE;$output|ForEach-Object{[string]$_};if($code -ne 0){throw 'Restored journal checks failed'}
  'signin_admin_journal_5_source_negative_controls_and_restore_passed'
 }
}finally{[IO.Directory]::Delete($root,$true)}
exit 0
